using System.Collections.Generic; using UnityEngine; using ZombieDiner.Orders; [CreateAssetMenu(menuName="ZombieDiner/Recipe")] public class RecipeSO:ScriptableObject{public List<ItemSO> requiredIngredients; public DishSO resultDish; public bool Matches(List<ItemSO> c){if(c.Count!=requiredIngredients.Count)return false; var dict=new Dictionary<ItemSO,int>(); foreach(var i in requiredIngredients) dict[i]=dict.ContainsKey(i)?dict[i]+1:1; foreach(var i in c){if(!dict.ContainsKey(i)) return false; dict[i]--; if(dict[i]<0) return false;} return true;}}